document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const base=Number($('base').value),tipo=$('tipo').value;const r=TempoTools.multa(base,tipo);if(!r){show('<h2>Check the amount</h2><p>Enter a positive value and select the severity of the case.</p>');return;}show('<p class="eyebrow">A hypothetical '+({leve:'minor',grave:'serious'}[tipo])+' infringement</p><h2>Indicative percentage range</h2><p class="amount">'+money(r.min)+' — '+money(r.max)+'</p><p>Base entered: <strong>'+money(base)+'</strong>. Percentages applied: <strong>'+(tipo==='leve'?'0.1% to 0.7%':'0.7% to 1%')+'</strong>.</p><p>It is a multiplication of the base by the legal limits. It does not apply the individual quantification methodology or establish a likely fine. The authority determines the infringement and the sanction according to the circumstances and the principle of proportionality.</p><p>Alleged infringements are not added together and other liabilities or corrective measures are not included. This simulator does not cover personal fines for public servants or resolve cases without prior turnover.</p>'+finish());});